pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient wide but not zero to be realistic; zero is still allowed though
        // bound amount to a wide range to avoid overly large gas usage in some environments
        amount = bound(amount, 0, type(uint256).max);

        uint256 before = c.proposalCount();
        // call newGrantProposal as the fuzzer-provided caller
        vm.prank(address(uint160(uint256(keccak256(abi.encodePacked(recipient, amount, block.timestamp))))));
        // We do not expect revert; call and catch any unexpected revert
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct contract always succeeds and increments proposalCount by exactly 1.
        // For this universal property test we assert that if the call succeeded, proposalCount == before + 1.
        // This will hold for the reference and fail for the mutant for some inputs (where mutant increments twice).
        if (ok) {
            assertTrue(c.proposalCount() == before + 1);
        } else {
            // If the call reverted (unexpected for reference), still assert false to fail the test on reference if it ever reverts
            assertTrue(false);
        }
    }
}

