    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient non-zero to be a realistic address; still wide domain
        if(recipient == address(0)) recipient = address(1);

        // record proposalCount before
        uint256 before = c.proposalCount();

        // call newGrantProposal with fuzzed inputs
        // use a prank so msg.sender is not the zero address (not strictly necessary)
        vm.prank(address(123));
        c.newGrantProposal(recipient, amount);

        // exactly one assertion reading c's public getter
        // Reference: proposalCount should not be forcibly reset to 1 for all inputs.
