pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 startCount, address recipient, uint256 amount) public {
        // keep startCount in a reasonable range so that increment won't overflow
        startCount = bound(startCount, 0, type(uint256).max - 10);
        // If startCount > 0 we need to simulate that the contract already had proposals.
        // There is no setter for proposalCount, but newGrantProposal increments from current value.
        // So we call newGrantProposal startCount times to reach that starting state.
        // Use a nonzero recipient to avoid any potential zero-address checks elsewhere.
        if (recipient == address(0)) recipient = address(1);

        // Drive contract to desired starting proposalCount by repeated calls
        for (uint256 i = 0; i < startCount; ++i) {
            c.newGrantProposal(recipient, amount);
        }

        // read before
        uint256 before = c.proposalCount();

        // perform the action under test once
        c.newGrantProposal(recipient, amount);

        // read after
        uint256 after = c.proposalCount();

        // General rule: the official contract increments proposalCount by exactly 1 on each newGrantProposal
        // (mutant that sets proposalCount = 1 will violate this for many startCount values)
        assertTrue(after == before + 1);
    }
}

