        c.init(_vader, _usdv, _vault);
        // read the two public state variables via their autogenerated getters
        address vaderAddr = c.VADER();
        address usdvAddr = c.USDV();
        // final single assertion: on the original contract this holds for all inputs, but the mutant sets VADER == USDV
        assert(vaderAddr != usdvAddr);
    }

    // allow receiving ether in case it's needed by calling contexts
    receive() external payable {}
}

