contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the minimal sequence: init -> newAddressProposal -> _finalise via voteProposal -> wait and finaliseProposal
    // We can't actually advance block.timestamp here; instead we rely on the contract's logic to allow finaliseProposal to proceed
    // after _finalise was set by voteProposal, and finaliseProposal requires (block.timestamp - mapPID_timeStart) > coolOffPeriod.
    // To satisfy that in a verifier, caller supplies a large enough coolOffPeriod by calling init and then the test asserts finaliseProposal does not revert.

    function runTest(address vader, address usdv, address vault, address proposed) public {
        // initialize the contract
        c.init(vader, usdv, vault);
        // create a UTILS-type proposal
        c.newAddressProposal(proposed, "UTILS");
        // vote to trigger finalising state (calls internal _finalise)
        c.voteProposal(1);
        // We must ensure coolOffPeriod passed. The contract sets coolOffPeriod = 1 in init, and mapPID_timeStart set to block.timestamp.
        // To ensure (block.timestamp - mapPID_timeStart) > coolOffPeriod, we simply call finaliseProposal and expect it not to revert on P.
        // On P this will call moveUtils which uses VADER (set during init) and should succeed; on M VADER is zero causing an external call to address(0) and revert.
        c.finaliseProposal(1);
        // Assert that the proposal was finalised: mapPID_finalised[1] == true (public getter)
        // This will be true on the original but false or reverted on the mutant.
        assert(c.mapPID_finalised(1) == true);
    }
    // Allow receiving ETH if needed
    receive() external payable {}
}

